import React, { useRef, useMemo, useState } from 'react';
import { useFrame, useLoader } from '@react-three/fiber';
import { Float, Text, useScroll, Sparkles, Grid, Trail, Sphere, Instance, Instances } from '@react-three/drei';
import * as THREE from 'three';

// ----------------------------------------------------
// NEURAL CORE (Custom Shader)
// ----------------------------------------------------
const coreVertexShader = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vDisplacement;
  varying vec3 vNormal;

  // Classic 3D noise (Simplex/Perlin approximation)
  vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
  vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
  
  float snoise(vec3 v){ 
    const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
    const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);
    vec3 i  = floor(v + dot(v, C.yyy) );
    vec3 x0 = v - i + dot(i, C.xxx) ;
    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min( g.xyz, l.zxy );
    vec3 i2 = max( g.xyz, l.zxy );
    vec3 x1 = x0 - i1 + 1.0 * C.xxx;
    vec3 x2 = x0 - i2 + 2.0 * C.xxx;
    vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;
    i = mod(i, 289.0 ); 
    vec4 p = permute( permute( permute( 
               i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
             + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
             + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));
    float n_ = 1.0/7.0; 
    vec3  ns = n_ * D.wyz - D.xzx;
    vec4 j = p - 49.0 * floor(p * ns.z *ns.z);
    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_ );
    vec4 x = x_ *ns.x + ns.yyyy;
    vec4 y = y_ *ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);
    vec4 b0 = vec4( x.xy, y.xy );
    vec4 b1 = vec4( x.zw, y.zw );
    vec4 s0 = floor(b0)*2.0 + 1.0;
    vec4 s1 = floor(b1)*2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));
    vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
    vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;
    vec3 p0 = vec3(a0.xy,h.x);
    vec3 p1 = vec3(a0.zw,h.y);
    vec3 p2 = vec3(a1.xy,h.z);
    vec3 p3 = vec3(a1.zw,h.w);
    vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
    p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
    vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
    m = m * m;
    return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3) ) );
  }

  void main() {
    vUv = uv;
    vNormal = normal;
    
    // Animate noise over time
    float noiseFreq = 0.015;
    float noiseAmp = 30.0;
    vec3 noisePos = vec3(position.x * noiseFreq + uTime * 0.5, position.y * noiseFreq + uTime * 0.3, position.z * noiseFreq);
    float noise = snoise(noisePos);
    
    // Add micro details
    float noiseMicro = snoise(noisePos * 3.0) * 0.2;
    
    vDisplacement = noise + noiseMicro;
    
    vec3 newPosition = position + normal * (vDisplacement * noiseAmp);
    
    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
  }
`;

const coreFragmentShader = `
  uniform float uTime;
  varying vec2 vUv;
  varying float vDisplacement;
  varying vec3 vNormal;

  void main() {
    // Gradient based on displacement
    vec3 colorCore = vec3(0.02, 0.05, 0.2); // Deep blue
    vec3 colorEdge = vec3(0.0, 1.0, 1.0);   // Cyan
    vec3 colorHighlight = vec3(1.0, 1.0, 1.0); // White
    
    float mixFactor = smoothstep(-1.0, 1.0, vDisplacement);
    
    vec3 finalColor = mix(colorCore, colorEdge, mixFactor);
    if(mixFactor > 0.8) {
        finalColor = mix(finalColor, colorHighlight, (mixFactor - 0.8) * 5.0);
    }
    
    // Add rim lighting
    float viewNormal = 1.0 - max(dot(vNormal, vec3(0.0, 0.0, 1.0)), 0.0);
    finalColor += vec3(0.0, 0.5, 0.8) * pow(viewNormal, 3.0);

    gl_FragColor = vec4(finalColor, 0.95);
  }
`;

const AICore = ({ position }) => {
  const meshRef = useRef();
  const materialRef = useRef();

  const uniforms = useMemo(() => ({
    uTime: { value: 0 }
  }), []);

  useFrame((state, delta) => {
    if (materialRef.current) {
      materialRef.current.uniforms.uTime.value = state.clock.elapsedTime;
    }
    if (meshRef.current) {
      meshRef.current.rotation.y += delta * 0.2;
      meshRef.current.rotation.z -= delta * 0.1;
    }
  });

  return (
    <group position={position}>
      <mesh ref={meshRef}>
        <sphereGeometry args={[180, 128, 128]} />
        <shaderMaterial
          ref={materialRef}
          vertexShader={coreVertexShader}
          fragmentShader={coreFragmentShader}
          uniforms={uniforms}
          transparent={true}
          wireframe={false}
        />
      </mesh>
      
      {/* Outer energy shell */}
      <mesh scale={1.2}>
        <sphereGeometry args={[180, 64, 64]} />
        <meshBasicMaterial color="#00ffff" wireframe transparent opacity={0.03} />
      </mesh>
      
      <pointLight intensity={8} color="#00ffff" distance={1500} />
      <pointLight intensity={3} color="#0055ff" distance={800} position={[0, -200, 0]} />
    </group>
  );
};

// ----------------------------------------------------
// DATA HIGHWAY (Instanced Particles along Splines)
// ----------------------------------------------------
const DataHighway = () => {
  const meshRef = useRef();
  const count = 600;
  const resolution = 1000;
  
  // Create 5 distinct splines representing data channels
  // Precompute spaced points for hyper-efficient O(1) lookups
  const curvesData = useMemo(() => {
    const c = [];
    for(let i=0; i<5; i++) {
       const sign = i % 2 === 0 ? 1 : -1;
       const offset = (i * 200) - 400;
       const curve = new THREE.CatmullRomCurve3([
         new THREE.Vector3(offset, -1000, 1000),
         new THREE.Vector3(offset + 300 * sign, 200, 200),
         new THREE.Vector3(0, -200, -800), // Converge at core
         new THREE.Vector3(offset - 300 * sign, -500, -1500),
         new THREE.Vector3(offset, 1000, -2500)
       ]);
       c.push({ points: curve.getSpacedPoints(resolution) });
    }
    return c;
  }, []);

  // Shared matrix and vectors for garbage-free useFrame
  const dummy = useMemo(() => new THREE.Object3D(), []);
  const tempPos = useMemo(() => new THREE.Vector3(), []);
  const tempNext = useMemo(() => new THREE.Vector3(), []);
  
  const particles = useMemo(() => {
    const temp = [];
    for (let i = 0; i < count; i++) {
      temp.push({
        curveIndex: i % curvesData.length,
        progress: Math.random(),
        speed: 0.001 + Math.random() * 0.003,
        offset: new THREE.Vector3((Math.random()-0.5)*40, (Math.random()-0.5)*40, (Math.random()-0.5)*40),
        scale: 0.2 + Math.random() * 0.8
      });
    }
    return temp;
  }, [count, curvesData.length]);

  useFrame(() => {
    if (!meshRef.current) return;
    
    particles.forEach((p, i) => {
      p.progress += p.speed;
      if (p.progress >= 1) p.progress = 0;
      
      const cData = curvesData[p.curveIndex];
      
      // O(1) array lookup with linear interpolation
      const exactIdx = p.progress * resolution;
      const idx1 = Math.floor(exactIdx);
      const idx2 = Math.min(idx1 + 1, resolution);
      const fract = exactIdx - idx1;
      
      const p1 = cData.points[idx1];
      const p2 = cData.points[idx2];
      if (!p1 || !p2) return;

      tempPos.lerpVectors(p1, p2, fract).add(p.offset);
      
      dummy.position.copy(tempPos);
      dummy.scale.setScalar(p.scale);
      
      const lookIdx1 = Math.floor(Math.min((p.progress + 0.01) * resolution, resolution));
      const lookIdx2 = Math.min(lookIdx1 + 1, resolution);
      const lookP1 = cData.points[lookIdx1];
      const lookP2 = cData.points[lookIdx2];
      
      if (lookP1 && lookP2) {
          tempNext.lerpVectors(lookP1, lookP2, fract).add(p.offset);
          dummy.lookAt(tempNext);
      }
      
      dummy.updateMatrix();
      meshRef.current.setMatrixAt(i, dummy.matrix);
    });
    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <instancedMesh ref={meshRef} args={[null, null, count]}>
      <boxGeometry args={[4, 4, 30]} />
      <meshBasicMaterial color="#00ffff" transparent opacity={0.6} blending={THREE.AdditiveBlending} />
    </instancedMesh>
  );
};


// ----------------------------------------------------
// HOLOGRAPHIC HUD RINGS
// ----------------------------------------------------
const HUDRings = ({ position }) => {
  const groupRef = useRef();
  
  useFrame((state, delta) => {
    if(groupRef.current) {
      groupRef.current.children[0].rotation.z += delta * 0.1;
      groupRef.current.children[1].rotation.z -= delta * 0.15;
      groupRef.current.children[2].rotation.z += delta * 0.05;
    }
  });

  return (
    <group position={position} ref={groupRef}>
      <mesh>
        <ringGeometry args={[300, 302, 64]} />
        <meshBasicMaterial color="#0088ff" transparent opacity={0.4} side={THREE.DoubleSide} />
      </mesh>
      <mesh>
        <ringGeometry args={[320, 330, 64, 1, 0, Math.PI * 1.5]} />
        <meshBasicMaterial color="#00ffff" transparent opacity={0.6} side={THREE.DoubleSide} />
      </mesh>
      <mesh>
        <ringGeometry args={[350, 351, 64, 1, 0, Math.PI]} />
        <meshBasicMaterial color="#ffffff" transparent opacity={0.2} side={THREE.DoubleSide} />
      </mesh>
    </group>
  );
};


// ----------------------------------------------------
// MAIN WORLD COMPONENT
// ----------------------------------------------------
const WorldAutopilot = ({ position, rotation, visible }) => {
  const scroll = useScroll();
  const [hasLocked, setHasLocked] = useState(false);

  useFrame(() => {
    if (!visible) return;
    
    // Trigger scroll lock for Autopilot
    if (scroll.offset > 0.675 && scroll.offset < 0.69 && !hasLocked && !window.autopilotLocked) {
      window.autopilotLocked = true;
      setHasLocked(true);
      
      setTimeout(() => {
        window.autopilotLocked = false;
      }, 1500);
    }
    
    if ((scroll.offset < 0.65 || scroll.offset > 0.70) && hasLocked) {
      setHasLocked(false);
      window.autopilotLocked = false;
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      <ambientLight intensity={0.2} />
      
      {/* Deep Cyber Void */}
      <mesh rotation={[0, -Math.PI / 2, 0]}>
        <sphereGeometry args={[4000, 32, 32]} />
        <meshBasicMaterial color="#010204" side={THREE.BackSide} />
      </mesh>

      {/* Grid Floor */}
      <Grid 
        position={[0, -800, -800]} 
        args={[4000, 4000]} 
        cellSize={100} 
        cellThickness={1} 
        cellColor="#004455" 
        sectionSize={500} 
        sectionThickness={1.5} 
        sectionColor="#00aaff" 
        fadeDistance={2000} 
        fadeStrength={1} 
      />

      <AICore position={[0, -200, -800]} />
      
      <HUDRings position={[0, -200, -800]} />

      <DataHighway />

      {/* Atmospheric Particles */}
      <Sparkles count={2000} scale={3000} size={15} speed={0.1} opacity={0.2} color="#00ffff" position={[0, 0, -800]} />

      {/* Title Hologram & Logo */}
      <group position={[0, 300, -600]}>
        <Float speed={2} rotationIntensity={0.05} floatIntensity={0.5}>
          <Text font="/fonts/Roboto.woff" fallbackFonts={[]} position={[0, -50, 0]} fontSize={70} color="#ffffff" anchorX="center" anchorY="middle" outlineWidth={1} outlineColor="#00ffff">
              AUTOPILOT
          </Text>
          <Text font="/fonts/Roboto.woff" fallbackFonts={[]} position={[0, -120, 0]} fontSize={28} color="#00ffff" anchorX="center" anchorY="middle">
              Autonomous Business Agent
          </Text>
        </Float>
      </group>
    </group>
  );
};

export default WorldAutopilot;
